"""Anea national campaigns: authored gameplay, not newly asserted history.

Every row is a distinct focus. Historical subjects are gated; evergreen national
work stays useful across the three acts. See docs/ANEA_CAMPAIGNS.md for sources.
"""
from dataclasses import dataclass


@dataclass(frozen=True)
class Focus:
    tag: str
    suffix: str
    title: str
    desc: str
    phase: str
    kind: str
    x: int
    y: int
    prerequisite: tuple = ()
    excludes: tuple = ()
    reward: str = ''
    available: str = ''
    cost: int = 5
    ai: int = 35

    @property
    def id(self):
        return self.tag + '_an_' + self.suffix


FOCUSES = []


def prep(n):
    return f'add_to_variable = {{ ac_anea_preparedness = {n} }}\nac_anea_bound = yes'


def recover(n):
    return f'add_to_variable = {{ ac_anea_recovery = {n} }}\nac_anea_bound = yes'


def policy(tag, chosen, other):
    return (f'clr_country_flag = {tag}_an_{other}\n'
            f'remove_ideas = {tag}_an_{other}_spirit\n'
            f'set_country_flag = {tag}_an_{chosen}\n'
            f'add_ideas = {tag}_an_{chosen}_spirit')


def f(tag, suffix, title, desc, phase, kind, x, y, prerequisite=(), reward='',
      available='', cost=5, excludes=(), ai=35):
    row = Focus(tag, suffix, title, desc, phase, kind, x, y,
                tuple(tag + '_an_' + p for p in prerequisite),
                tuple(tag + '_an_' + p for p in excludes), reward, available,
                cost, ai)
    FOCUSES.append(row)
    return row


# A root, four independent four-node programmes, and an assessment: 18 nodes.
# Positions are absolute, so import order cannot change the resolved layout.
f('EMM', 'national_account', 'An Account of the Republic',
  'The new decade begins with more commitments than any single ministry can see. A common account of public services, productive capacity and the defence establishment will show where promises overlap. The cabinet must begin with what the country can sustain, rather than the strength it hopes to display.',
  'foundation', 'assembly', 12, 0, reward='set_country_flag = EMM_an_opening_ready', ai=100)
f('EVA', 'national_account', 'The State of the Federation',
  'Industrial reports, military returns and district accounts describe different countries. The administration needs one inventory of the roads, workshops and trained people it can actually call upon. Reconciling those accounts is a political undertaking: every corrected figure takes a promise away from someone who expected it to be honoured.',
  'foundation', 'document', 12, 0, reward='set_country_flag = EVA_an_opening_ready', ai=100)

FOUNDATION = {
 'EMM': [
  ('budget_review','The Public Budget Review','Published accounts will reveal which services depend on emergency appropriations year after year. Ministers can defend their priorities, but must also identify the people and equipment required to deliver them. The first review will establish a continuing argument over civilian provision and the protected defence allocation.','economy',2,2,('national_account',),'set_country_flag = EMM_an_allocation_ready'),
  ('civil_priority','Protect Civil Investment','Water systems, workshops and local transport form the productive base on which every other promise rests. Protecting their investment programme improves construction and public confidence, while leaving less capacity for military expansion. The services will have to make greater use of the forces already available.','civil',1,3,('budget_review',),policy('EMM','civil_priority','defence_priority')),
  ('defence_priority','Protect Defence Allocations','The services ask for a stable allocation rather than a succession of emergency purchases. A protected programme supports readiness and replacement production, while civilian ministries absorb more of the shortage. The cabinet accepts that a larger military establishment must be supported every year.','command',3,3,('budget_review',),policy('EMM','defence_priority','civil_priority')),
  ('annual_compact','The Annual Service Compact','National ministries and local authorities will agree which tasks can be funded before publishing their annual plans. The compact gives the selected budget policy an administrative foundation, but creates a permanent obligation to explain delays. It is a method of keeping promises manageable, rather than an unlimited spending programme.','document',2,4,('civil_priority','defence_priority'),'add_stability = 0.02\nadd_political_power = -20'),
  ('workshop_register','Register Productive Workshops','A national register will distinguish firms able to repair existing machinery from those equipped to manufacture replacements. Contracts can then be sized to real capacity. Smaller workshops gain a route into public work, and the government gains a more reliable account of its industrial reserves.','industry',8,2,('national_account',),'add_tech_bonus = { name = EMM_an_workshop_register bonus = 0.5 uses = 1 category = industry }'),
  ('freight_timetables','A Common Freight Timetable','Commercial rail operators and public depots use different priorities when traffic is heavy. A common timetable will reserve maintenance periods and identify substitute routes. The gains come from using the network more reliably; the scheme does not assume that every government consignment can jump ahead of civilian trade.','rail',8,3,('workshop_register',),'add_political_power = -15\nadd_ideas = EMM_an_freight_network_spirit'),
  ('supplier_standards','Supplier Inspection Standards','Interchangeable fittings and traceable inspection records matter when an urgent repair reaches an unfamiliar workshop. Suppliers will receive a common specification and a clear appeals process. Compliance costs will be shared through longer contracts instead of being disguised as free industrial efficiency.','tools',8,4,('freight_timetables',),'add_tech_bonus = { name = EMM_an_supplier_standards bonus = 0.5 uses = 1 category = industry }'),
  ('regional_contracts','Regional Maintenance Contracts','The transport and utilities ministries will offer standing contracts to crews outside the capital. Keeping those crews available consumes administrative attention, but reduces the dependence of distant districts on a single repair office. The same relationships can support domestic reconstruction if a later emergency disrupts normal procurement.','rebuild',8,5,('supplier_standards',),'add_political_power = -20\nadd_ideas = EMM_an_maintenance_service_spirit'),
  ('force_returns','Readiness beyond Paper Strength','The armed forces will report serviceable equipment, trained crews and available transport separately from nominal unit strength. An honest return may look less impressive, but it makes exercises and replacement orders possible. The first result will be a plan for sustaining existing formations.','command',16,2,('national_account',),'army_experience = 8\nair_experience = 5'),
  ('airfield_crews','Permanent Airfield Crews','Aircraft cannot disperse safely when every trained ground crew belongs to the main station. A permanent rotation will teach smaller airfields to refuel, inspect and service visiting aircraft. This investment supports military availability and does not substitute for civilian shelters or evacuation planning.','air',16,3,('force_returns',),'air_experience = 12\nadd_ideas = EMM_an_air_service_spirit'),
  ('coastal_patrols','Coordinate Coastal Patrols','Harbour authorities and naval watch officers will exchange a common shipping picture. Patrols can concentrate on gaps in coverage instead of duplicating reports from the busiest ports. The navy gains practice in sustained operations, while commercial traffic retains predictable access to the coast.','navy',16,4,('airfield_crews',),'navy_experience = 12'),
  ('reserve_transport','Reserve Transport Exercises','A short reserve exercise will follow equipment from depot to unit and back again. Rail timetables, fuel handling and maintenance returns will decide whether a formation can move without exhausting its support. The results improve military logistics without keeping a large reserve permanently mobilised.','training',16,5,('coastal_patrols',),'army_experience = 12\nadd_ideas = EMM_an_reserve_logistics_spirit'),
  ('regional_desks','Permanent Regional Desks','Diplomats need a working record of commercial delays, transport rules and consular problems before a crisis arrives. Permanent desks will maintain those contacts between visits by ministers. Their routine work preserves channels for practical agreements without committing the republic to a new military alignment.','diplomacy',24,2,('national_account',),'add_political_power = -15\nadd_stability = 0.01'),
  ('civil_contacts','Civil Technical Contacts','Engineers and administrators can compare inspection methods even when governments disagree about larger questions. Technical contacts will focus on sanitation, transport and public works. They offer a modest improvement in domestic practice while leaving the cabinet free to decide the scope of later cooperation.','science',24,3,('regional_desks',),'add_tech_bonus = { name = EMM_an_civil_contacts bonus = 0.5 uses = 1 category = electronics }'),
  ('consular_rota','A Consular Emergency Rota','Consulates will name the officials responsible for missing-person enquiries, travel documents and emergency communications. A rota cannot provide unlimited assistance, but it prevents the first requests from disappearing between offices. The cabinet will retain this civil capacity alongside its ordinary diplomatic work.','communications',24,4,('civil_contacts',),'add_stability = 0.02\nadd_political_power = -15'),
  ('neighbour_protocols','Practical Neighbour Protocols','The regional desks will put their work into a set of contact and document protocols. These arrangements cover civilian enquiries and technical assistance, with no automatic promise of troops or money. A later government will inherit functioning channels while retaining responsibility for each substantive commitment.','diplomacy',24,5,('consular_rota',),'set_country_flag = EMM_an_neighbour_protocols'),
 ],
 'EVA': [
  ('allocation_review','The Allocation Register','District requests and service orders repeatedly reserve the same transport and machinery. A common register will force the administration to acknowledge the shortfall. It must then choose whether distribution is subject to public audit or concentrated in the command chain that can move resources most quickly.','economy',2,2,('national_account',),'set_country_flag = EVA_an_allocation_ready'),
  ('audited_distribution','Audit Civil Distribution','A civilian inspection service will track public allocations from the warehouse to the receiving district. Publishing the record makes diversion harder and protects confidence in the administration. Commanders lose discretion over some supplies, and the inspectors require staff who could otherwise support military readiness.','document',1,3,('allocation_review',),policy('EVA','audited_distribution','command_distribution')),
  ('command_distribution','Distribution through the Command Chain','The command chain will concentrate requisition authority and keep trained formations supplied. It can act quickly, but civilian offices have fewer ways to challenge an order or prove that a promised delivery never arrived. The administration accepts this loss of confidence in exchange for a more dependable military allocation.','command',3,3,('allocation_review',),policy('EVA','command_distribution','audited_distribution')),
  ('district_liaisons','District Liaison Officers','Every district will have a named liaison who can trace a request through the chosen allocation system. The officers cannot eliminate shortages, but they can prevent officials from treating an unanswered form as a completed delivery. Maintaining the service imposes a continuing administrative burden on the centre.','assembly',2,4,('audited_distribution','command_distribution'),'add_stability = 0.02\nadd_political_power = -20'),
  ('industrial_returns','Correct the Industrial Returns','Factories will separate installed machinery from machinery that can actually run a full shift. Inspectors will record shortages of power, parts and skilled labour. Honest returns reduce impressive production claims, while making it possible to direct limited investment towards work that can be completed.','industry',8,2,('national_account',),'add_tech_bonus = { name = EVA_an_industrial_returns bonus = 0.5 uses = 1 category = industry }'),
  ('rail_dispatch','A National Rail Dispatch Office','Local dispatchers face incompatible priorities from civilian ministries and the services. A national office will keep a visible order of work and a reserve for breakdowns. Its success depends on limiting exceptional orders rather than promising that every claimant can receive priority.','rail',8,3,('industrial_returns',),'add_ideas = EVA_an_dispatch_service_spirit\nadd_political_power = -20'),
  ('repair_cooperatives','Workshop Repair Cooperatives','Small workshops will pool scarce gauges, specialist tools and repair knowledge. This offers a practical way to restore equipment without waiting for an entirely new plant. Public contracts will pay for availability as well as output, tying part of the industrial budget to maintenance.','tools',8,4,('rail_dispatch',),'add_tech_bonus = { name = EVA_an_repair_cooperatives bonus = 0.5 uses = 1 category = industry }'),
  ('industrial_reserve','Protect the Maintenance Reserve','A reserve of spares is easy to consume when production targets are missed. A protected maintenance allocation will keep worn machinery in service, although it reduces the resources available for immediate expansion. The government must defend this less visible investment against more impressive new programmes.','industry',8,5,('repair_cooperatives',),'add_ideas = EVA_an_industrial_reserve_spirit\nadd_political_power = -25'),
  ('command_returns','Inspect Command Readiness','Inspectors will compare the strength claimed by headquarters with the transport, equipment and trained crews held by each formation. Units that can deploy safely will receive first call on the exercise programme. The inspection measures readiness without treating civilian allocations as a military reserve.','command',16,2,('national_account',),'army_experience = 10'),
  ('air_maintenance','An Air Maintenance Establishment','The air arm needs a permanent system for inspection intervals, replacement parts and instructor rotations. A maintenance establishment will concentrate that knowledge and provide deployable crews. Keeping it staffed carries a cost, but protects aircraft already bought from becoming expensive entries in a ledger.','air',16,3,('command_returns',),'air_experience = 12\nadd_ideas = EVA_an_air_maintenance_spirit'),
  ('coastal_support','Support the Coastal Flotillas','Small fleets require dependable fuel handling and shore maintenance more than ambitious declarations of naval power. Support teams will rehearse the return of damaged vessels and the movement of stores between ports. The programme improves naval endurance without creating a strategic fleet that the country cannot sustain.','navy',16,4,('air_maintenance',),'navy_experience = 12'),
  ('mobile_workshops','Mobile Military Workshops','Army workshops will practise moving with the formations they support, carrying the tools required for common breakdowns. This makes the existing force easier to sustain in an exercise or an emergency. It also reserves skilled mechanics for the military when civilian industry would welcome their labour.','logistics',16,5,('coastal_support',),'army_experience = 10\nadd_ideas = EVA_an_mobile_workshops_spirit'),
  ('foreign_records','Reconcile Foreign Commitments','The foreign office will compile the commercial and technical obligations spread across several ministries. A signed agreement is useful only if the office responsible for delivery knows what it promised. Reconciling the record preserves freedom of action while making later requests for assistance more credible.','document',24,2,('national_account',),'add_political_power = -15\nadd_stability = 0.01'),
  ('technical_exchanges','Civil Technical Exchanges','Civil engineers will exchange inspection procedures and repair methods with willing neighbours. The programme concerns ordinary public works, and it does not grant a foreign government authority over domestic decisions. Practical contacts can nevertheless keep a useful channel open when political relations are strained.','science',24,3,('foreign_records',),'add_tech_bonus = { name = EVA_an_technical_exchanges bonus = 0.5 uses = 1 category = electronics }'),
  ('border_documents','Standardise Civil Documents','Clear travel and cargo documents reduce the opportunity for local officials to impose their own requirements. The administration will publish a common set of forms and a contact for disputes. Predictability costs some discretion, but improves confidence in routine dealings across the frontier.','diplomacy',24,4,('technical_exchanges',),'add_political_power = -15\nadd_stability = 0.02'),
  ('neighbour_channels','Keep Neighbour Channels Open','The foreign office will maintain a small permanent channel for transport, public-health and missing-person enquiries. Its work is deliberately narrower than a military alliance. Even a government pursuing self-reliance will benefit from being able to ask a precise question and receive an accountable answer.','communications',24,5,('border_documents',),'set_country_flag = EVA_an_neighbour_channels'),
 ]}
for tag, rows in FOUNDATION.items():
    for suffix,title,desc,kind,x,y,prereq,reward in rows:
        excludes = {'civil_priority':('defence_priority',),'defence_priority':('civil_priority',),
                    'audited_distribution':('command_distribution',),'command_distribution':('audited_distribution',)}.get(suffix,())
        ai = {'civil_priority':70,'defence_priority':25,'audited_distribution':15,'command_distribution':80}.get(suffix,35)
        f(tag,suffix,title,desc,'foundation',kind,x,y,prereq,reward,cost=10 if suffix in ('annual_compact','district_liaisons','industrial_reserve','regional_contracts') else 5,excludes=excludes,ai=ai)
    f(tag,'national_programme','A Sustainable National Programme' if tag=='EMM' else 'Commitments the State Can Keep',
      'The initial inventory has become a working programme. Its value lies in recording the costs that annual plans used to hide: maintenance, trained staff, transport and the opportunity to challenge an allocation. Future governments can change the priorities, but will inherit institutions capable of explaining the consequences.',
      'foundation','assembly',12,7,('annual_compact' if tag=='EMM' else 'district_liaisons',),'add_stability = 0.02\nadd_political_power = -15',cost=10)


