        if suffix=='recovery_assessment': available += ' date > 2004.12.31'
        ai = {'broad_assistance':70,'conditional_assistance':40,'monitored_access':70,'domestic_self_reliance':25}.get(suffix,40)
        f(tag,suffix,title,desc,'recovery',kind,x,y,prereq,reward,available,cost=10 if suffix in ('standing_services','balanced_readiness','local_recovery','command_settlement','recovery_assessment') else 5,excludes=excludes,ai=ai)


